// Security headers applied by the Worker to every response (Workers do not process public/_headers).
// Keep the CSP in sync with the <meta> CSP in index.html: tests/security.test.js enforces it.
// Security headers applied by the Worker to every response (Workers do not process public/_headers).
// Keep the CSP in sync with the Vite-transformed <meta> CSP in index.html.
function connectionSources(supabaseUrl){
 try{
  const url=new URL(supabaseUrl);
  const isSupabase=url.hostname.endsWith('.supabase.co')||url.hostname.endsWith('.supabase.in');
  const isLocal=['localhost','127.0.0.1','[::1]'].includes(url.hostname);
  if((url.protocol!=='https:'&&!isLocal)||(url.protocol==='https:'&&!isSupabase))return '';
  const socketProtocol=url.protocol==='https:'?'wss:':'ws:';
  return `${url.origin} ${socketProtocol}//${url.host}`;
 }catch{return '';}
}
export function createCsp(supabaseUrl,includeFrameAncestors=false){
 const sources=connectionSources(supabaseUrl);
 return `default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'${sources?' '+sources:''}; worker-src 'self' blob:; media-src 'self' blob:; object-src 'none'; base-uri 'self'; form-action 'self'${includeFrameAncestors?"; frame-ancestors 'none'":''}`;
}
export const CSP_BASE=createCsp();
export function createSecurityHeaders(supabaseUrl){
 return {
 'Content-Security-Policy':createCsp(supabaseUrl,true),
 'Strict-Transport-Security':'max-age=31536000; includeSubDomains',
 'X-Frame-Options':'DENY',
 'X-Content-Type-Options':'nosniff',
 'Referrer-Policy':'no-referrer',
 'Permissions-Policy':'camera=(), geolocation=(), microphone=(self)',
 'Cross-Origin-Opener-Policy':'same-origin'
 };
}
export const SECURITY_HEADERS=createSecurityHeaders();

export async function proxyAI(request,route,config,requestFetch=fetch){
 const json=(error,status)=>Response.json({error},{status,headers:{'Cache-Control':'no-store'}});
 if(request.method!=='POST')return json('Użyj POST.',405);
 const auth=request.headers.get('Authorization');if(!auth?.startsWith('Bearer '))return json('Zaloguj się.',401);
 if(!config?.url||!config?.publishableKey)return json('Usługa Supabase nie została skonfigurowana.',503);
 const reader=request.body?.getReader();let chunks=[],size=0;if(reader)for(;;){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>(route==='ocr'?3000000:12000)){await reader.cancel();return json('Za duże żądanie.',413);}chunks.push(value);}
 const body=new Uint8Array(size);let offset=0;for(const c of chunks){body.set(c,offset);offset+=c.length;}
 try{const response=await requestFetch(config.url.replace(/\/+$/,'')+'/functions/v1/student-ai/'+route,{method:'POST',headers:{Authorization:auth,apikey:config.publishableKey,'Content-Type':'application/json'},body,signal:AbortSignal.timeout(120000)});return new Response(response.body,{status:response.status,headers:{'Content-Type':'application/json','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});}catch{return json('Usługa AI nie odpowiedziała. Spróbuj później.',502);}
}

const SUPABASE_CONFIG={"url":"https://djnshtlhcsaxayxmeijz.supabase.co","publishableKey":"sb_publishable_e9aVkD8bgOnoNG_AwqPLFQ_1wpNjzfo"};
const SECURITY_HEADERS=createSecurityHeaders(SUPABASE_CONFIG.url);
const ASSETS={"/assets/index-CITwvLBh.css":{"body":"","type":"text/css"},"/assets/index-D4Y4RSeZ.js":{"body":"","type":"text/javascript"},"/assets/pdf.worker.min-CjEcRF4W.mjs":{"body":"","type":"text/javascript"},"/assets/student-files-t5dRSdIW.js":{"body":"","type":"text/javascript"},"/index.html":{"body":"","type":"text/html; charset=utf-8"}};;;
async function route(request){const url=new URL(request.url);if(url.pathname==='/api/task-help')return proxyAI(request,'task-help',SUPABASE_CONFIG);if(url.pathname==='/api/ocr')return proxyAI(request,'ocr',SUPABASE_CONFIG);if(url.pathname==='/api/study')return proxyAI(request,'study',SUPABASE_CONFIG);if(url.pathname.startsWith('/api/'))return new Response('Not found',{status:404});const asset=ASSETS[url.pathname]||(url.pathname==='/'?ASSETS['/index.html']:null);if(!asset)return new Response('Not found',{status:404});return new Response(request.method==='HEAD'?null:Uint8Array.from(atob(asset.body),c=>c.charCodeAt(0)),{headers:{'Content-Type':asset.type,'X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer','Cache-Control':url.pathname.startsWith('/assets/')?'public,max-age=31536000,immutable':'no-cache'}});}
export default {async fetch(request,env){const res=await route(request);const out=new Response(res.body,res);for(const [k,v] of Object.entries(SECURITY_HEADERS))out.headers.set(k,v);return out;}};